import{_ as l,l as s,o as e,c as i,v as m,p as d,x as t,d as o,i as p,S as T,b as r}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"循环 Transformer","description":"","frontmatter":{"title":"循环 Transformer","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/looped-transformer.md","filePath":"llm/looped-transformer.md","lastUpdated":1789023840000}'),h={name:"llm/looped-transformer.md"};function f(u,a,c,_,B,E){const n=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=m('<h1 id="循环-transformer" tabindex="-1">循环 Transformer <a class="header-anchor" href="#循环-transformer" aria-label="Permalink to &quot;循环 Transformer&quot;">​</a></h1><div class="epigraph"><p>把同一 Transformer 块循环足够多次，可以模拟可编程的迭代算法；循环次数是测试时的计算旋钮。</p><footer>—— Giannou et al., Looped Transformers as Programmable Computers, ICML 2023</footer></div><p><a href="/llm/universal-transformer-recurrence">上一课</a>带 ACT 的共享块，停机门把课序弄复杂。现代工作常去掉自适应，改成<strong>固定或测试时选择的循环次数 \\(T\\)</strong>：训练用中等 \\(T\\)，推理对难题加大 \\(T\\)。这就是 looped Transformer。它接 Universal 的参数共享，但把计算预算从每位置门收到一个全局整数。下一课早退会把预算再按层或按 token 切开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ACT 的停机门难训，批内不同步。需要一种更硬的陈述：若 \\(F_\\theta\\) 足够表达，则 \\(F_\\theta^{\\circ T}\\) 可以模拟多步算法（复制、计数、简单程序），\\(T\\) 增大等于多给计算，而不改参数。缺口是把这件事写成与权重解耦的<strong>测试时计算</strong>，并标明它与「加不共享的层」在泛化上的差别。</p><p>Giannou 等人给出构造性结果：在理想化设定下，looped Transformer 可模拟计算机。后续经验工作用循环块做算术、长度外推、推理链。本课取机制，不把某篇竞赛级算术论文展开成词条。</p><p><span class="marginnote">循环次数 \\(T\\) 不是序列长度 \\(n\\)。\\(n\\) 仍由注意力二次项决定。\\(T\\) 决定块应用多少次。长上下文与多步思考不是同一轴，尽管都贵。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选 \\(k\\) 层作为一个循环体（\\(k=1\\) 最干净），前面可留若干不共享的 prelude 层写表示，后面可留 coda 层读结果。中间对循环体应用 \\(T\\) 次，每次都带残差与归一化。训练对 \\(T\\sim T_{\\mathrm{train}}\\) 或对 \\(T\\) 做随机抽样，使模型习惯不同迭代深度。推理设 \\(T_{\\mathrm{test}}\\ge T_{\\mathrm{train}}\\)，观察是否还能改进——这是「算力换准确」是否成立的检验。</p><p>输入可以每步重新注入（像 RNN 读 \\(x_t\\)，但这里 \\(x\\) 是整段），也可以只在 \\(t=0\\) 注入。重新注入有助于避免状态遗忘任务条件；只注入一次则更像对隐状态做独立迭代。</p><h3 id="与加层的参数账" tabindex="-1">与加层的参数账 <a class="header-anchor" href="#与加层的参数账" aria-label="Permalink to &quot;与加层的参数账&quot;">​</a></h3><p>\\(L=kT\\) 的不共享模型参数约 \\(T\\) 倍于循环体。循环模型用一份参数换 \\(T\\) 次计算。若任务真是同一规则迭代，循环更参数高效；若每层需要不同规则，循环会欠拟合，必须加大 \\(k\\) 或放弃共享。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每次循环，注意力看见的是上一轮混合后的整段状态，因此可以多步传播信息：第一步把局部证据写入某些位置，第二步远端查询再读这些位置。这与加深不共享模型类似，但强制每步用同一套路由参数，电路必须可复用。不能复用时，增大 \\(T\\) 会振荡或饱和，而不是单调变好——这是诊断：若 \\(T_{\\mathrm{test}}\\) 加大立刻变差，说明训练没覆盖该预算，或任务根本不是迭代算法。</p><p>Prelude/coda 的存在承认「输入嵌入」和「输出解码」往往不应共享中间推理块的权重，这与 Universal Transformer 把一切塞进 \\(F_\\theta\\) 的极端设定不同。</p><p><span class="marginnote">梯度穿过 \\(T\\) 次 \\(F_\\theta\\)，与激活检查点一起决定能否训大 \\(T\\)。实践中 \\(T_{\\mathrm{train}}\\) 往往小于希望的 \\(T_{\\mathrm{test}}\\)，外推计算步数并不自动成立。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Looped 不是免费的推理时思考。每加一循环就加一整段注意力 FLOPs，延迟线性涨。对语言建模困惑度，共享循环常常弱于同样 FLOPs 的不共享深层模型，因为语言模型不是整齐的迭代算法。本课的适用边界是算法化、可多步改进的任务，以及参数极度受限时。下一课早退把「不必跑满 \\(T\\)」从全局整数改回按例决策。</p>',18)),(e(),d(T,null,{default:t(()=>[p(n,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20In%5B%22%E8%BE%93%E5%85%A5%22%5D%20--%3E%20P%5B%22Prelude%20%E4%B8%8D%E5%85%B1%E4%BA%AB%22%5D%0A%20%20P%20--%3E%20Loop%5B%22%E5%85%B1%E4%BA%AB%E5%9D%97%20x%20T%22%5D%0A%20%20Loop%20--%3E%20Loop%0A%20%20Loop%20--%3E%20C%5B%22Coda%20%E4%B8%8D%E5%85%B1%E4%BA%AB%22%5D%0A%20%20C%20--%3E%20Out%5B%22%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r("h2",{id:"小结",tabindex:"-1"},[o("小结 "),r("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=r("ul",null,[r("li",null,"Looped Transformer 用全局循环次数 \\(T\\) 当测试时计算旋钮，去掉 ACT 的每位置门。"),r("li",null,"同一规则的迭代任务上，参数远少于同等深度的不共享栈。"),r("li",null,"\\(T_{\\mathrm{test}}\\gt T_{\\mathrm{train}}\\) 不自动变好；振荡说明规则不可复用或预算没训到。"),r("li",null,"语言模型困惑度往往更吃不共享的深度。"),r("li",null,"出处：Giannou et al., ICML 2023。")],-1))])}const b=l(h,[["render",f]]);export{P as __pageData,b as default};
